INSERT INTO collection_pages VALUES('bfc70c6e1b2998b9a39b61c1b83e1efe0fe98b037fddfbf3be7a7d97c63fc995','bbcf117595af373aa80a9834dbf3ef0bb9ed08280ca81a23427cd2079a4d2c5b','{"hasNext":false,"items":[{"author":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"authoredDate":"2026-05-06T13:30:43Z","committedDate":"2026-05-06T13:30:43Z","committer":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"observedAt":"2026-10-08T22:53:48.744Z","repositoryId":1229374397,"sha":"1e9659711ea103c0d0e47d9d19ac3532510f4b23"},{"author":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"authoredDate":"2026-05-05T02:01:26Z","committedDate":"2026-05-05T02:01:26Z","committer":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"observedAt":"2026-10-08T22:53:48.744Z","repositoryId":1229374397,"sha":"41d4cef774880e5954b1c7b86affcfb452e77116"},{"author":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"authoredDate":"2026-05-05T01:28:22Z","committedDate":"2026-05-05T01:28:22Z","committer":{"account":{"login":"nareshdama","providerType":"User"},"email":"nareshyadavdama@gmail.com","name":"nareshdama"},"observedAt":"2026-10-08T22:53:48.744Z","repositoryId":1229374397,"sha":"3c3656d32f9d265b85783f73494ae6411d7643a5"}],"observedAt":"2026-10-08T22:53:48.744Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/149917774?v=4","events_url":"https://api.github.com/users/nareshdama/events{/privacy}","followers_url":"https://api.github.com/users/nareshdama/followers","following_url":"https://api.github.com/users/nareshdama/following{/other_user}","gists_url":"https://api.github.com/users/nareshdama/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/nareshdama","id":149917774,"login":"nareshdama","node_id":"U_kgDOCO-QTg","organizations_url":"https://api.github.com/users/nareshdama/orgs","received_events_url":"https://api.github.com/users/nareshdama/received_events","repos_url":"https://api.github.com/users/nareshdama/repos","site_admin":false,"starred_url":"https://api.github.com/users/nareshdama/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/nareshdama/subscriptions","type":"User","url":"https://api.github.com/users/nareshdama","user_view_type":"public"},"comments_url":"https://api.github.com/repos/nareshdama/CardDue/commits/1e9659711ea103c0d0e47d9d19ac3532510f4b23/comments","commit":{"author":{"date":"2026-05-06T13:30:43Z","email":"nareshyadavdama@gmail.com","name":"nareshdama"},"comment_count":0,"committer":{"date":"2026-05-06T13:30:43Z","email":"nareshyadavdama@gmail.com","name":"nareshdama"},"message":"Fix payment double-mark bug; add autopay-bounce verification flow\n\nThe Quick Pay button could be tapped repeatedly because markPaid mutated\ndueDate on every call, which broke the cycle-membership check used to\ndetect \"already paid this cycle\". Cycle anchoring is now computed\ndynamically via effectiveDueDate(), and PAYMENT_PAID activities are\nstamped with the cycleDueDate they were made for. markPaid is\nidempotent per cycle.\n\nAlso adds autopay-aware states (AT_RISK, MISSED) and T-1 / T+1 / T+3\nnudges so a silent autopay bounce — issuer attempts deduction, bank\nshort, returned-payment fee + late fee — gets surfaced before the\nwindow to act manually closes. Confirmation flow gives the user three\nexplicit choices: Cleared / Bounced / Not sure.\n\nUI kept minimal: min payment now visible on the card row, bounce pill\nappears only when there''s a recent bounce, statement rollover is a\nsingle inline form on the PAID banner.\n\nCo-Authored-By: Claude Opus 4.7 <noreply@anthropic.com>","tree":{"sha":"64344d521042aebba390194f28aeb33aace0c9b5","url":"https://api.github.com/repos/nareshdama/CardDue/git/trees/64344d521042aebba390194f28aeb33aace0c9b5"},"url":"https://api.github.com/repos/nareshdama/CardDue/git/commits/1e9659711ea103c0d0e47d9d19ac3532510f4b23","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/149917774?v=4","events_url":"https://api.github.com/users/nareshdama/events{/privacy}","followers_url":"https://api.github.com/users/nareshdama/followers","following_url":"https://api.github.com/users/nareshdama/following{/other_user}","gists_url":"https://api.github.com/users/nareshdama/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/nareshdama","id":149917774,"login":"nareshdama","node_id":"U_kgDOCO-QTg","organizations_url":"https://api.github.com/users/nareshdama/orgs","received_events_url":"https://api.github.com/users/nareshdama/received_events","repos_url":"https://api.github.com/users/nareshdama/repos","site_admin":false,"starred_url":"https://api.github.com/users/nareshdama/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/nareshdama/subscriptions","type":"User","url":"https://api.github.com/users/nareshdama","user_view_type":"public"},"html_url":"https://github.com/nareshdama/CardDue/commit/1e9659711ea103c0d0e47d9d19ac3532510f4b23","node_id":"C_kwDOSUbDvdoAKDFlOTY1OTcxMWVhMTAzYzBkMGU0N2Q5ZDE5YWMzNTMyNTEwZjRiMjM","parents":[{"html_url":"https://github.com/nareshdama/CardDue/commit/41d4cef774880e5954b1c7b86affcfb452e77116","sha":"41d4cef774880e5954b1c7b86affcfb452e77116","url":"https://api.github.com/repos/nareshdama/CardDue/commits/41d4cef774880e5954b1c7b86affcfb452e77116"}],"sha":"1e9659711ea103c0d0e47d9d19ac3532510f4b23","url":"https://api.github.com/repos/nareshdama/CardDue/commits/1e9659711ea103c0d0e47d9d19ac3532510f4b23"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/149917774?v=4","events_url":"https://api.github.com/users/nareshdama/events{/privacy}","foll