os/amourgit/Core-Frontend-EGEN/commits/b0a82355fa7629bc157cb9c1dcfa2cfc20413b54"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/164351680?v=4","events_url":"https://api.github.com/users/amourgit/events{/privacy}","followers_url":"https://api.github.com/users/amourgit/followers","following_url":"https://api.github.com/users/amourgit/following{/other_user}","gists_url":"https://api.github.com/users/amourgit/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/amourgit","id":164351680,"login":"amourgit","node_id":"U_kgDOCcvOwA","organizations_url":"https://api.github.com/users/amourgit/orgs","received_events_url":"https://api.github.com/users/amourgit/received_events","repos_url":"https://api.github.com/users/amourgit/repos","site_admin":false,"starred_url":"https://api.github.com/users/amourgit/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/amourgit/subscriptions","type":"User","url":"https://api.github.com/users/amourgit","user_view_type":"public"},"comments_url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/commits/35c1bf9c9ccf125464bb741c666558ece88796da/comments","commit":{"author":{"date":"2026-05-16T08:56:39Z","email":"nzilasamuel2021@outlook.fr","name":"NZILA NGALA Amour Samuel"},"comment_count":0,"committer":{"date":"2026-05-16T08:56:39Z","email":"nzilasamuel2021@outlook.fr","name":"NZILA NGALA Amour Samuel"},"message":"fix(mf): crash ReactCurrentDispatcher — double instance React","tree":{"sha":"842b86020c3798bb9dfd593f51023505f81e784f","url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/git/trees/842b86020c3798bb9dfd593f51023505f81e784f"},"url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/git/commits/35c1bf9c9ccf125464bb741c666558ece88796da","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/164351680?v=4","events_url":"https://api.github.com/users/amourgit/events{/privacy}","followers_url":"https://api.github.com/users/amourgit/followers","following_url":"https://api.github.com/users/amourgit/following{/other_user}","gists_url":"https://api.github.com/users/amourgit/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/amourgit","id":164351680,"login":"amourgit","node_id":"U_kgDOCcvOwA","organizations_url":"https://api.github.com/users/amourgit/orgs","received_events_url":"https://api.github.com/users/amourgit/received_events","repos_url":"https://api.github.com/users/amourgit/repos","site_admin":false,"starred_url":"https://api.github.com/users/amourgit/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/amourgit/subscriptions","type":"User","url":"https://api.github.com/users/amourgit","user_view_type":"public"},"html_url":"https://github.com/amourgit/Core-Frontend-EGEN/commit/35c1bf9c9ccf125464bb741c666558ece88796da","node_id":"C_kwDOSVQQitoAKDM1YzFiZjljOWNjZjEyNTQ2NGJiNzQxYzY2NjU1OGVjZTg4Nzk2ZGE","parents":[{"html_url":"https://github.com/amourgit/Core-Frontend-EGEN/commit/baf4b36c136bf50c646fed0e480ec0e3df4c1631","sha":"baf4b36c136bf50c646fed0e480ec0e3df4c1631","url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/commits/baf4b36c136bf50c646fed0e480ec0e3df4c1631"}],"sha":"35c1bf9c9ccf125464bb741c666558ece88796da","url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/commits/35c1bf9c9ccf125464bb741c666558ece88796da"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/commits/baf4b36c136bf50c646fed0e480ec0e3df4c1631/comments","commit":{"author":{"date":"2026-05-15T07:39:00Z","email":"claude@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2026-05-15T07:39:00Z","email":"claude@anthropic.com","name":"Claude"},"message":"fix(esm-styleguide): correct ThemeContextType re-export with type keyword\n\nRoot cause:\n  In theme/index.ts, ThemeContextType is declared as:\n    export type { ..., ThemeContextType, ... } from ''./types'';\n\n  But in public.ts it was re-exported WITHOUT the type keyword:\n    export { ..., ThemeContextType } from ''./theme/index'';  ← WRONG\n\n  This causes webpack to warn:\n    export ''ThemeContextType'' (reexported as ''ThemeContextType'') was not found\n    in ''./theme/index'' (possible exports: DarkModeToggle, ThemeColorPreview, ...)\n\n  Because with ''export type'', the symbol only exists at compile time —\n  it has NO runtime presence and webpack cannot resolve it as a value.\n\nFix:\n  Use the inline type qualifier (TypeScript 4.5+):\n    export { ..., type ThemeContextType } from ''./theme/index'';  ← CORRECT\n\n  This tells both TypeScript and webpack that it''s a type-only re-export,\n  which is correct and suppresses the warning entirely.","tree":{"sha":"03185110717e23081b43d6c40c97a97a653ea746","url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/git/trees/03185110717e23081b43d6c40c97a97a653ea746"},"url":"https://api.github.com/repos/amourgit/Core-Frontend-EGEN/git/commits/baf4b36c136bf50c646fed0e480ec0e3df4c1631","verification":{"