vents_url":"https://api.github.com/users/web-flow/events{/privacy}","followers_url":"https://api.github.com/users/web-flow/followers","following_url":"https://api.github.com/users/web-flow/following{/other_user}","gists_url":"https://api.github.com/users/web-flow/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/web-flow","id":19864447,"login":"web-flow","node_id":"MDQ6VXNlcjE5ODY0NDQ3","organizations_url":"https://api.github.com/users/web-flow/orgs","received_events_url":"https://api.github.com/users/web-flow/received_events","repos_url":"https://api.github.com/users/web-flow/repos","site_admin":false,"starred_url":"https://api.github.com/users/web-flow/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/web-flow/subscriptions","type":"User","url":"https://api.github.com/users/web-flow","user_view_type":"public"},"html_url":"https://github.com/Layott/evotv-app/commit/9070c77545cf6d7f5207b003066d77d78ed32d74","node_id":"C_kwDOSVUfFtoAKDkwNzBjNzc1NDVjZjZkN2Y1MjA3YjAwMzA2NmQ3N2Q3OGVkMzJkNzQ","parents":[{"html_url":"https://github.com/Layott/evotv-app/commit/e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a","sha":"e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a","url":"https://api.github.com/repos/Layott/evotv-app/commits/e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a"},{"html_url":"https://github.com/Layott/evotv-app/commit/905c39573e46478a30fc8875234e877fc02d5c92","sha":"905c39573e46478a30fc8875234e877fc02d5c92","url":"https://api.github.com/repos/Layott/evotv-app/commits/905c39573e46478a30fc8875234e877fc02d5c92"}],"sha":"9070c77545cf6d7f5207b003066d77d78ed32d74","url":"https://api.github.com/repos/Layott/evotv-app/commits/9070c77545cf6d7f5207b003066d77d78ed32d74"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/90828865?v=4","events_url":"https://api.github.com/users/Layott/events{/privacy}","followers_url":"https://api.github.com/users/Layott/followers","following_url":"https://api.github.com/users/Layott/following{/other_user}","gists_url":"https://api.github.com/users/Layott/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Layott","id":90828865,"login":"Layott","node_id":"MDQ6VXNlcjkwODI4ODY1","organizations_url":"https://api.github.com/users/Layott/orgs","received_events_url":"https://api.github.com/users/Layott/received_events","repos_url":"https://api.github.com/users/Layott/repos","site_admin":false,"starred_url":"https://api.github.com/users/Layott/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Layott/subscriptions","type":"User","url":"https://api.github.com/users/Layott","user_view_type":"public"},"comments_url":"https://api.github.com/repos/Layott/evotv-app/commits/905c39573e46478a30fc8875234e877fc02d5c92/comments","commit":{"author":{"date":"2026-08-17T22:17:00Z","email":"ladilawalt@gmail.com","name":"ladilawalt"},"comment_count":0,"committer":{"date":"2026-08-17T22:17:00Z","email":"ladilawalt@gmail.com","name":"ladilawalt"},"message":"Send x-amz-acl on the APK upload so the download is not 403\n\nThe first published build looked like a success from every angle except the one\nthat matters. The PUT returned 200, the release row was written, /apps/android\nstarted offering the link, and fetching that link answered 403 AccessDenied.\n\nThe server signs the upload with `ACL: public-read`, but the AWS SDK hoists\n`x-amz-*` into the query string when presigning and Spaces does not apply the ACL\nfrom there, so the object landed private. Sending the header explicitly on the\nPUT applies it.\n\nWorth stating plainly: a release nobody can download is worse than no release,\nbecause the page claims it works and the failure only shows up on a viewer''s\nphone. Verified after the fix by fetching the published URL: 200, 101,341,593\nbytes, content-type application/vnd.android.package-archive.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_014GkRDBJorYUURn4bkNe7JW","tree":{"sha":"3199c4bbd4fe5d5e27277396736c28a20024850b","url":"https://api.github.com/repos/Layott/evotv-app/git/trees/3199c4bbd4fe5d5e27277396736c28a20024850b"},"url":"https://api.github.com/repos/Layott/evotv-app/git/commits/905c39573e46478a30fc8875234e877fc02d5c92","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/90828865?v=4","events_url":"https://api.github.com/users/Layott/events{/privacy}","followers_url":"https://api.github.com/users/Layott/followers","following_url":"https://api.github.com/users/Layott/following{/other_user}","gists_url":"https://api.github.com/users/Layott/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Layott","id":90828865,"login":"Layott","node_id":"MDQ6VXNlcjkwODI4ODY1","organizations_url":"https://api.github.com/users/Layott/orgs","received_events_url":"https://api.github.com/users/Layott/received_events","repos_url":"https://api.github.com/users/Layott/repos","site_admin":false,"starred_url":"https://api.github.com/users/Layott/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Layott/subscriptions","type":"User","url":"https://api.github.com/users/Layott","user_view_type":"public"},"html_url":"https://github.com/Layott/evotv-app/commit/905c39573e46478a30fc8875234e877fc02d5c92","node_id":"C_kwDOSVUfFtoAKDkwNWMzOTU3M2U0NjQ3OGEzMGZjODg3NTIzNGU4NzdmYzAyZDVjOTI","parents":[{"html_url":"https://github.com/Layott/evotv-app/commit/e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a","sha":"e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a","url":"https://api.github.com/repos/Layott/evotv-app/commits/e504d9db5632e5f01dcaefa3e9bb79de7f3b3b8a"}],"sha":"905c39573e46478a30fc8875234e877fc02d5c92","url":"https://api.github.com/repos/Layott/evotv-app/commits/905c39573e46478a30fc8875234e877fc02d5c92"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/90828865?v=4","events_url":"https://api.github.com/users/Layott/events{/p